sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float rows;
uniform float speed;
uniform float alternate;
uniform float randomSpeed;
uniform float seed;
uniform float vertical;
uniform float gap;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float hash21(float2 p) {
    return fract(sin(dot(p, float2(127.1, 311.7))) * 43758.5453);
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float n = max(floor(rows + 0.5), 1.0);
    float axisPos = vertical > 0.5 ? coord.x : coord.y;
    float axisLen = vertical > 0.5 ? size.x : size.y;
    float row = floor(axisPos / axisLen * n);
    float f = fract(axisPos / axisLen * n);
    float dirn = alternate > 0.5 ? (mod(row, 2.0) > 0.5 ? -1.0 : 1.0) : 1.0;
    float rnd = 1.0 + (hash21(float2(row, seed)) - 0.5) * 2.0 * randomSpeed;
    float off = dirn * rnd * time * speed;
    float other = vertical > 0.5 ? coord.y : coord.x;
    float otherLen = vertical > 0.5 ? size.y : size.x;
    float w = fract(other / otherLen + off) * otherLen;
    float2 q = vertical > 0.5 ? float2(coord.x, w) : float2(w, coord.y);
    float keep = step(gap * 0.5, f) * step(f, 1.0 - gap * 0.5);
    return fin(c, tex(q) * keep, opacity);
}
